mapper.select:
select u.user_id as id, u.user_name as userName, coalesce(nullif(u.nick_name, ''), u.user_name) as displayName, d.dept_name as departmentName from sys_user u left join sys_dept d on d.dept_id = u.dept_id and d.status = '0' and d.del_flag = '0' where u.status = '0' and u.del_flag = '0' and exists ( select 1 from sys_user_role ur inner join sys_role r on r.role_id = ur.role_id where ur.user_id = u.user_id and r.status = '0' and r.del_flag = '0'
and r.role_key = #{roleKey}
and r.role_key in ('lab_student', 'lab_manager', 'lab_safety_officer', 'lab_repair_worker', 'lab_system_admin')
)
and (u.user_name like concat('%', #{keyword}, '%') or u.nick_name like concat('%', #{keyword}, '%') or d.dept_name like concat('%', #{keyword}, '%'))
order by u.user_id limit 100
